import { listarAtividades } from './atividades.js'

const ALFABETO = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

export function buscarEncontro(id) {
  for (const atividade of listarAtividades()) {
    const encontro = atividade.encontros.find(e => e.id === id)
    if (encontro) {
      return { atividade, encontro }
    }
  }
  return null
}

export function dentroDaJanela(instante, inicio) {
  const t = Date.parse(instante)
  const i = Date.parse(inicio)
  return t >= i - 15 * 60_000 && t <= i + 30 * 60_000
}

export function codigoDoMinuto(instante) {
  const indice = Math.floor(Date.parse(instante) / 60_000)
  let resto = indice
  let codigo = ''
  for (let i = 0; i < 6; i += 1) {
    codigo += ALFABETO[resto % ALFABETO.length]
    resto = Math.floor(resto / ALFABETO.length)
  }
  return codigo
}

export function trocaDeCodigo(instante) {
  const indice = Math.floor(Date.parse(instante) / 60_000)
  return {
    trocaEm: new Date((indice + 1) * 60_000).toISOString(),
    validoAte: new Date((indice + 2) * 60_000).toISOString()
  }
}

export function resetPresencas() {}

